 const el=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let selected='presidencia',step=1,report=null,edited=false,source=null,draft=null,canEdit=false,busy=false,dirty=false;let cache={};
 const message=t=>el('assembly-cloud-status').textContent=t;
 async function api(route,input){const r=await fetch('/api/'+route,{method:input?'POST':'GET',credentials:'same-origin',headers:input?{'Content-Type':'application/json'}:{},body:input?JSON.stringify(input):undefined});let d;try{d=await r.json();}catch{throw Error('No se pudo consultar la plataforma.');}if(!r.ok)throw Error(d.error||'No se pudo completar la operación.');return d;}
 function context(){const asada=el('assembly-asada').value,year=Number(el('assembly-year').value),start=el('as-start').value,end=el('as-end').value;if(!asada||!Number.isInteger(year)||year<1900||year>2200)throw Error('Seleccione la ASADA y un año válido.');if(!start||!end||start>end||!start.startsWith(year+'-')||!end.startsWith(year+'-'))throw Error('Seleccione un período dentro del año consultado, con fechas inicial y final válidas.');return {asada,year,start,end};}
 function lock(on){busy=on;for(const id of ['assembly-asada','assembly-year','assembly-type','assembly-import','assembly-load-draft','assembly-save-draft','as-start','as-end','assembly-profile-import'])el(id).disabled=on||(id==='assembly-save-draft'&&!canEdit);}
 function read(){const d={};for(const k of ['name','author','start','end','meeting'])d[k]=el('as-'+k).value.trim();d.answers={};el('assembly-fields').querySelectorAll('[data-question-text]').forEach(t=>{const key=t.dataset.questionText;d.answers[key]={text:t.value,status:el('q-status-'+key).value};});d.conclusion=el('as-conclusion')?.value||'';d.projects=readItems('projects');d.followups=readItems('followups');d.financeConfirmed=el('assembly-finance-confirm').checked;return d;}
 function readItems(kind){return [...el('assembly-'+kind).querySelectorAll('[data-repeat-item]')].map(item=>Object.fromEntries([...item.querySelectorAll('[data-item-field]')].map(x=>[x.dataset.itemField,x.value])));}
